{
  "messages": [
    {"role": "system", "content": "You extract a regulation citation. Reply with JSON having exactly two fields: `regulation` (a string, one of GDPR or EU AI Act) and `article` (an integer)."},
    {"role": "user", "content": "Which article of the GDPR requires a record of processing activities?"}
  ],
  "response_format": {
    "type": "json_schema",
    "json_schema": {
      "name": "citation",
      "schema": {
        "type": "object",
        "properties": {
          "regulation": {"type": "string"},
          "article": {"type": "integer"}
        },
        "required": ["regulation", "article"],
        "additionalProperties": false
      }
    }
  },
  "temperature": 0.7
}

{
  "findingId": "{{finding_id}}",
  "reason": "Not applicable: we process no special-category data"
}

{
  "fields": {
    "name": "Payroll",
    "purpose": "Paying staff and meeting tax obligations",
    "legalBasis": "Article 6(1)(b), performance of a contract",
    "dataCategories": ["name", "bank details"],
    "recipients": ["our accountant"],
    "retentionPeriod": "7 years after employment ends"
  }
}

{
  "fields": {
    "name": "CV ranking model",
    "vendor": "",
    "purpose": "Ranks applicants for shortlisting",
    "riskClassification": "high",
    "documentationStatus": "missing"
  },
  "reviewed": true
}

{
  "aiSystemId": "{{ai_system_id}}",
  "fields": {
    "name": "CV ranking model",
    "vendor": "",
    "purpose": "Ranks applicants for shortlisting",
    "riskClassification": "limited",
    "documentationStatus": "in_progress"
  },
  "reviewed": true
}

{
  "pack": {
    "packId": "example",
    "obligations": [
      {
        "slug": "example-obligation",
        "title": "An example",
        "summary": "At least one hundred characters of plain-language summary, because this is the text a person reads to decide whether a finding applies to them.",
        "citation": {
          "kind": "article",
          "celex": "32016R0679",
          "articleNumber": 30
        },
        "severity": "high",
        "actionType": "create_ropa"
      }
    ]
  },
  "dryRun": true
}

{
  "orgId": "{{org_id}}",
  "delegation": "",
  "signal": "We are a 40 person recruitment agency. We hold candidate CVs and employee payroll records, and we have never written down what we do with them.",
  "obligations": [
    {
      "slug": "gdpr-art-30-ropa",
      "title": "Records of Processing Activities",
      "summary": "Article 30 GDPR requires a written record of what you do with personal data, why, and for how long."
    }
  ]
}
